            { interval: "40,000 km", timeLimit: "4 years", task: "Cabin Microfilter Replacement", details: "Replace the dual cabin filters to ensure maximum HVAC efficiency and clean interior air.", parts: ["Cabin Filter Kit"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "40 EUR" }
