        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B48 is a masterpiece of modern engineering. The closed-deck design provides a highly rigid cylinder area, allowing for massive reliable turbo boost. It entirely cured the fragility of the older N20 generation.", crankshaft: "Forged Steel, supported by 5 main bearings, with twin balance shafts to mitigate 4-cylinder vibrations.", pistonSpeed: "14.2 m/s @ 6000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features an 11.0:1 compression ratio optimized for efficiency.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "16-valve DOHC design. Flow is highly optimized for immediate turbo response. The head integrates the Valvetronic and Double-VANOS systems for infinite variability.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH sides. Driven by the rear timing chain cassette.", lifterType: "Hydraulic bucket tappets.", specialFeature: "F49 Long-Wheelbase Architecture. This specific 'C' engine code was targeted towards the Chinese market F49 Long-Wheelbase X1. The transverse engine provides maximum cabin space, resulting in 7-Series levels of rear legroom in a compact crossover." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "108°C Electronically mapped heat management.", oilCooler: "Integrated heat exchanger on the oil filter housing." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "250 Bar (Fuel Rail). Driven by a mechanical HPFP.", injectors: "4x Bosch Solenoid Injectors. Highly robust." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (The transverse Aisin transmission is the limiting factor).", maxSafePowerStock: "350 hp (The B48 block easily handles this power with bolt-ons and a tune).", maxSafeRPM: "6500 RPM", weakestLink: "Engine Mounts (Rapid Wear), Plastic Vent Line (Snaps), Expansion Tank (Leaks), PCV Valve." }, electrical: { coils: "Individual Coil Pack system (4x Coil-on-Plug).", ecu: "Bosch MG1 (Highly tunable via OBD)." } },
        recommendedParts: { description: "Crucial maintenance parts to manage transverse engine mount wear and prevent catastrophic cooling failures on the B48.", parts: [ { category: "Billet Coolant Vent Hose Flange", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the brittle plastic cylinder head line that snaps." }, { category: "Engine Mount (Right Side)", brand: "Lemförder / Corteco", note: "CRITICAL: Replace every 80k km to stop violent cabin vibrations." }, { category: "Coolant Expansion Tank & Cap", brand: "Genuine BMW", note: "CRITICAL: Replaces the weeping plastic tank before a blowout." }, { category: "Valve Cover Assembly (with PCV)", brand: "Victor Reinz / BMW", note: "CRITICAL: Replaces the integrated torn PCV membrane." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Prevents oil leaks down the front of the block." }, { category: "Spark Plugs", brand: "NGK SILZKGR8B8S", note: "Require specific 12-point socket." }, { category: "Electric Water Pump", brand: "Pierburg", note: "Replace proactively around 100k km." }, { category: "Serpentine Belt Kit", brand: "INA", note: "Replace to prevent accessory loss." } ] },
