            { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifold and blast the intake ports with crushed walnut shells to clear the massive carbon/EGR sludge buildup that chokes the B37.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "350 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "CRITICAL: Proactively replace the heavy main crankshaft pulley. The rubber core tears and will eventually destroy the serpentine belt system.", parts: ["Corteco Damper"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay Replacement", details: "Replace all 3 glow plugs and the glow plug control module. Essential for cold weather starting and triggering mandatory DPF regenerations.", parts: ["3x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "120 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "EGR Valve Cleaning/Replacement", details: "Remove and thoroughly clean or replace the EGR valve if the engine experiences rough idling or hesitation.", parts: ["BorgWarner Valve"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" }
