          { partName: "Haldex Filter Screen Kit", category: "Drivetrain", oem: { brand: "BMW Genuine", code: "N/A", approxPrice: "150 EUR" }, crossRef: { brand: "BorgWarner", code: "2003085", approxPrice: "85 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=2003085", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=2003085" }, note: "Mandatory for xDrive models." }
