            { interval: "30,000 km", timeLimit: "3 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "40 EUR" }
